head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.cnt = 0;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name ins_search
 * @description 투자계약증권 표준코드관리  목록 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    if ((txb_pSTD_CD.getValue() === "" || txb_pSTD_CD.getValue().indexOf(" ") === "") &&
        (txb_pISU_NM.getValue() === "" || txb_pISU_NM.getValue().indexOf(" ") === "") &&
        (txb_pISUR_CD.getValue() === "" || txb_pISUR_CD.getValue().indexOf(" ") === "") &&
        (edt_pSTD_CD_GRNT_DD_SDATE.getValue() === "" || edt_pSTD_CD_GRNT_DD_SDATE.text.indexOf(" ") === "") &&
        (edt_pSTD_CD_GRNT_DD_EDATE.getValue() === "" || edt_pSTD_CD_GRNT_DD_EDATE.text.indexOf(" ") === "")) {
        await $c.win.alert("조회 파라메터가 부족합니다");
        return;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_pISU_DD_SDATE, edt_pISU_DD_EDATE) === false) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE) === false) {
        return false;
    }

    // 데이터셋 초기화
    dts_List.removeAll();
    dts_detail.removeAll();

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20220922
    fn_SetDisableSelectBtn(btn_search, true);

    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_detail
 * @description 수익증권 표준코드관리 상세 조회한다.
 * @param {String} STD_CD STD_CD
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_detail = async function(STD_CD) {
    // 데이터셋 초기화
    dts_detail.removeAll();

    // 수익증권 표준코드관리
    const sbmOptions = {
        id : "sbm_dts_detail",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_detail=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_modify
 * @description 투자계약증권 표준코드관리 저장 , 수정 한다. screenProcsTpCd 02,03
 * @param {String} mflag mflag
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_modify = async function(mflag) {
    let screenProcsTpCd = "03";
    if (screenProcsTpCd === '03') {
        // 수정

        if (!$c.cp.isModified(dts_detail)) {
            await $c.win.alert("변경된 데이터가 없습니다.");
            return false;
        }
        if (txb_ISU_KOR_NM.getValue() === "" || txb_ISU_KOR_NM.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목명"));
            txb_ISU_KOR_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_KOR_NM, 80, "한글종목명")) {
            // txb_ISU_NM.value = "";
            txb_ISU_KOR_NM.focus();
            return false;
        }
        if (txb_ISU_KOR_ABBRV.getValue() === "" || txb_ISU_KOR_ABBRV.getValue().indexOf(" ") === "" || txb_ISU_KOR_ABBRV.getValue() === " ") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목약명"));
            txb_ISU_KOR_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_KOR_ABBRV, 40, "한글종목약명")) {
            // txb_ISU_KOR_ABBRV.value = "";
            txb_ISU_KOR_ABBRV.focus();
            return false;
        }
        if (txb_ISU_ENG_NM.getValue() === "" || txb_ISU_ENG_NM.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목명"));
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 80, "영문종목명")) {
            // txb_ISU_ENG_NM.value = "";
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (txb_ISU_ENG_ABBRV.getValue() === "" || txb_ISU_ENG_ABBRV.getValue().indexOf(" ") === "" || txb_ISU_ENG_ABBRV.getValue() === " ") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목약명"));
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 40, "영문종목약명")) {
            // txb_ISU_ENG_ABBRV.value = "";
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (txb_JNT_BZ_NM.getValue() === "" || txb_JNT_BZ_NM.getValue().indexOf(" ") === "" || txb_JNT_BZ_NM.getValue() === " ") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "공동사업명"));
            txb_JNT_BZ_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_JNT_BZ_NM, 60, "공동사업명")) {
            txb_JNT_BZ_NM.focus();
            return false;
        }
        if (edt_ISU_AMT.getValue() === "") {
            tab_UsrInfo.setSelectedTabIndex(1);
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행금액"));
            edt_ISU_AMT.focus();
            return false;
        }
        if (cmb_CURR_TP_CD.getValue() === "") {
            tab_UsrInfo.setSelectedTabIndex(1);
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행통화"));
            cmb_CURR_TP_CD.focus();
            return false;
        }
        if (cmb_ISU_TP_CD.getValue() === "") {
            tab_UsrInfo.setSelectedTabIndex(1);
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행구분"));
            cmb_ISU_TP_CD.focus();
            return false;
        }
        if (cmb_INVST_CONTRT_ISU_METHD_TP_CD.getValue() === "") {
            tab_UsrInfo.setSelectedTabIndex(1);
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행방법"));
            cmb_INVST_CONTRT_ISU_METHD_TP_CD.focus();
            return false;
        }
        if (edt_CONTRT_STRT_DD.getValue() === "") {
            tab_UsrInfo.setSelectedTabIndex(1);
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "계약시작일자"));
            edt_CONTRT_STRT_DD.focus();
            return false;
        }
        if (edt_CONTRT_END_DD.getValue() === "") {
            tab_UsrInfo.setSelectedTabIndex(1);
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "계약종료일자"));
            edt_CONTRT_END_DD.focus();
            return false;
        }
        // 날짜포맷 체크
        if (fn_CheckDateObj(edt_CONTRT_STRT_DD, "계약시작일자")) return false;
        if (fn_CheckDateObj(edt_CONTRT_END_DD, "계약종료일자")) return false;
        if (cmb_CRWFND_YN.getValue() === "") {
            tab_UsrInfo.setSelectedTabIndex(1);
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "크라우드펀딩여부"));
            cmb_CRWFND_YN.focus();
            return false;
        }
        if (txb_PL_REVR_REL_CONTN.getValue() === "" || txb_PL_REVR_REL_CONTN.getValue().indexOf(" ") === "" || txb_PL_REVR_REL_CONTN.getValue() === " ") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "손익귀속관련사항"));
            txb_PL_REVR_REL_CONTN.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_PL_REVR_REL_CONTN, 60, "손익귀속관련사항")) {
            txb_PL_REVR_REL_CONTN.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_SPECL_CONTRT_CONTN, 60, "특약사항")) {
            txb_SPECL_CONTRT_CONTN.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_MEMO_CONTN, 200, "담당자메모")) {
            txb_MEMO_CONTN.focus();
            return false;
        }
        if (mflag === "N") return;
        dts_detail.setCellData(dts_detail.getRowPosition(), "CRUDSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
        trs_modify.KeyName = "toinb_dataid4";
        // [전환검토] trs_modify.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     EMP_NO : js_emp_no,
        //     EMP_NM : js_emp_nm,
        //     EMAIL : js_email
        // };
        const sbmOptions = {
            id : "sbm_trs_modify",
            action : "/StdCdInvestInfoAction.do",
            ref : "dts_Rst,dts_detail",
            target : "trs_modify=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name ins_remove
 * @description 표준코드 삭제
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_remove = async function() {
    let screenProcsTpCd = "04";
    // dts_Delete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_Delete.insertRow();
    dts_Delete.setCellData(1, "STD_CD", dts_detail.getCellData(dts_detail.getRowPosition(), "STD_CD"));
    dts_Delete.setCellData(1, "ISU_NM", dts_detail.getCellData(dts_detail.getRowPosition(), "ISU_NM"));
    dts_Delete.setCellData(1, "CHG_RSN", txb_DEL_RSN.getValue());
    trs_Delete.KeyName = "toinb_dataid4";
    // [전환검토] trs_Delete.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm
    // };
    const sbmOptions = {
        id : "sbm_trs_Delete",
        action : "/StdCdInvestInfoAction.do",
        ref : "dts_Delete",
        target : "trs_Delete=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name Change_mf_cfi
 * @description 증권투자회사/부동산투자회사의 cfi 변경 설정
 * @returns {void}
 * @hidden N
 */
scwin.Change_mf_cfi = function() {
    //
    // Cfi의 콤보 박스를 변경할 경우....
    let cfi = "";
    cfi = "EU";
    if (cmb_mf_cfi_attr_1.getValue() === "") cfi += "_";

    else cfi += cmb_mf_cfi_attr_1.getValue();
    if (cmb_mf_cfi_attr_2.getValue() === "") cfi += "_";

    else cfi += cmb_mf_cfi_attr_2.getValue();
    if (cmb_mf_cfi_attr_3.getValue() === "") cfi += "_";

    else cfi += cmb_mf_cfi_attr_3.getValue();
    if (cmb_mf_cfi_attr_4.getValue() === "") cfi += "_";

    else cfi += cmb_mf_cfi_attr_4.getValue();
    txb_CFI_CD.setValue(cfi); // cfi 설정

};

/**********************************************
 * 함수명   : fn_GetParam
 * 설명       : 전달값을 정의한다.
 ***********************************************/
scwin.arrPar = new Array();

/**
 * @method
 * @name getParam
 * @description get Param 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // 표준코드 OR 발행기관 코드
    scwin.arrPar[1] = txb_param2.getValue();

    // alert(arrPar[0] + " " + arrPar[1]);
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name setFnGetParam
 * @description set Fn Get Param 처리
 * @param {*} vparam1 vparam1
 * @returns {void}
 * @hidden N
 */
scwin.setFnGetParam = function(vparam1) {
    txb_param1.setValue(vparam1);
    txb_param2.setValue("");
    fn_GetPar = scwin.getParam;
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    // PanelToGroupBox(panel_4);
    // PanelToGroupBox(panel_6);

    txb_pSTD_CD.setValue("KRH");
    ins_combo_set(dts_CURR_TP_CD, "ULDINS16600.xml", SCREN_PROCS_TP_CD_01, "02475", "SEL"); // 발행통화코드
    ins_combo_set(dts_ISU_TP_CD, "ULDINS16600.xml", SCREN_PROCS_TP_CD_01, "03407", "SEL"); // 발행구분(국내/해외)//03869
    ins_combo_set(dts_INVST_CONTRT_ISU_METHD_TP_CD, "ULDINS16600.xml", SCREN_PROCS_TP_CD_01, "03348", "SEL"); // 투자계약증권발행방법
    ins_combo_set(dts_COM_ATTR_TP_CD, "ULDINS16600.xml", SCREN_PROCS_TP_CD_01, "00840", "SEL"); // 회사속성
    ins_combo_set(dts_STD_CD_APCT_TP_CD, "ULDINS16600.xml", SCREN_PROCS_TP_CD_01, "03527"); // 03527 - 신청자구분
    fn_CtrlBtn_temp("no_data");
    txb_DEL_RSN.hide();
    txb_param1.hide();
    txb_param2.hide();
    txa_REF_CONTN.hide();

    // 2016.09.20 표준코드 ID 생성으로 인한 필요없는 항목 삭제----------------------------------
    btn_clearPwd.hide();
    // 2016.09.20 표준코드 ID 생성으로 인한 필요없는 항목 삭제----------------------------------

    const arrObjectApct = [txb_APCT_NM, txb_APCT_FAX_NO, txb_APCT_TEL_NO, txb_APCT_INNR_NO];
    for (let i = 0; i < arrObjectApct.length; i++) {
        fn_apct_delchar(arrObjectApct[i]);
    }
    txb_pSTD_CD.focus();
};

/**
 * @method
 * @name btn_prcnm_onclick
 * @description 「처리자조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_prcnm_onclick = function() {
    txb_param1.setValue(txb_STD_CD.getValue()); // 표준코드
    txb_param2.setValue("");
    fn_GetPar = scwin.getParam;
    ins_popupOpen("", "", "ULDINS93300", "표준코드 처리자 조회", "590", "420");
};

/**
 * @method
 * @name btn_file_onclick
 * @description 「첨부파일확인」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_file_onclick = function() {
    /*
    txb_param1 에는 신청ID
    txb_param2 에는 구분값을 넣는데..
     + "1 : 발행기관신청, 팩스-발행기관신청 \n"
     + "2 : 표준코드신청, 팩스-표준코드신청 \n"
     + "3 : 팩스-다운로드IP 로 값을 넣어주세요.\n"
     */
    txb_param1.setValue(dts_detail.getCellData(1, "STD_CD_APPL_ID")); // 표준코드 신청 ID
    txb_param2.setValue("2");
    fn_GetPar = scwin.getParam;
    ins_popupOpen("", "", "ULDINS91100", "첨부파일", "655", "350");
};

/**
 * @method
 * @name img_CONTRT_STRT_DD_onclick
 * @description img_CONTRT_STRT_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_CONTRT_STRT_DD_onclick = function() {
    popUpCalendar2(edt_ISU_DD);
};

/**
 * @method
 * @name img_CONTRT_END_DD_onclick
 * @description img_CONTRT_END_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_CONTRT_END_DD_onclick = function() {
    popUpCalendar2(edt_EXP_DD);
};

/**
 * @method
 * @name img_COM_NM_INFO_onclick
 * @description img_COM_NM_INFO 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_COM_NM_INFO_onclick = function() {
    txb_param1.setValue(txb_ISUR_CD.getValue()); // 발행기관코드
    txb_param2.setValue(txb_ISUR_NM.getValue()); // 발행기관명
    fn_GetPar = scwin.getParam;
    ins_popupOpen("", "", "ULDINS91600", "발행기관 상세정보", "740", "835");
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    fn_CtrlBtn_temp("no_data");
    if (dts_List.errorMsg) {
        await $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    scwin.cnt = rowcount;

    // 조회버튼 활성.
    fn_SetDisableSelectBtn(btn_search, false);
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    await $c.win.alert(dts_List);
    scwin.cnt = 0;

    // 조회버튼 활성.
    fn_SetDisableSelectBtn(btn_search, false);
};

/**
 * @method
 * @name dts_detail_OnLoadCompleted
 * @description dts_detail 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_detail_OnLoadCompleted = function(rowcount) {
    fn_CtrlBtn_temp("update");
    if (dts_detail.getCellData(dts_detail.rowpositon, "LIST_STAT_CD") === "Y") {
        // alert(" 상장종목은 수정할 수 없습니다. \n 공시총괄팀과 협의하시기 바랍니다.");
        btn_modify.setDisabled(true);
        btn_modify.setBackgroundImage("../img/ins/btn_modify_d.gif");
        btn_delete.setDisabled(true);
        btn_delete.setBackgroundImage("../img/ins/btn_delete_d.gif");

        // alert 삭제 및 비밀번호 초기화도 제어 추가 20140116
        btn_clearPwd.setDisabled(true);
        btn_clearPwd.setBackgroundImage("../img/ins/btn_clearPwd_d.gif");
    }
};

/**
