    txb_param2.setValue(txb_ISUR_NM.getValue()); // 발행기관명
    fn_GetPar = scwin.getParam;
    ins_isuNmpopupOpen(txb_ISU_KOR_NM, txb_ISU_KOR_ABBRV, txb_ISU_ENG_NM, txb_ISU_ENG_ABBRV); // 종목기준명 호출

